import zipfile
import os
from tkinter import simpledialog
folder_path = simpledialog.askstring('폴더 경로 입력', '압축할 폴더 경로를 입력하세요:')
if not folder_path:
    print('❌ 경로가 입력되지 않았습니다.')
else:
    folder_path = folder_path.strip('"')
    if not os.path.isdir(folder_path):
        print('❌ 유효한 폴더 경로가 아닙니다.')
    else:
        folder_name = os.path.basename(folder_path.rstrip('/\\'))
        zip_filename = os.path.join(folder_path, folder_name + '.zip')
        file_paths = []
        for root, _, files in os.walk(folder_path):
            for file in files:
                path = os.path.join(root, file)
                if path != zip_filename:
                    file_paths.append((path, os.path.relpath(path, folder_path)))
        zipf = zipfile.ZipFile(zip_filename, 'w')
        for full, rel in file_paths:
            zipf.write(full, rel)
        zipf.close()
        print('✅ 압축 완료:', zip_filename)

import os
import re
from tkinter import simpledialog
folder_path = simpledialog.askstring('폴더 경로 입력', '정리할 폴더 경로를 입력하세요:')
if not folder_path or not os.path.isdir(folder_path):
    print('❌ 유효한 폴더 경로가 아닙니다.')
else:
    files = os.listdir(folder_path)
    originals = set()
    duplicates = []
    for f in files:
        match = re.match(r'^(.*?)( - 복사본)?(\..+)?$', f)
        if match:
            base = (match.group(1) or '') + (match.group(3) or '')
            if ' - 복사본' in f:
                duplicates.append(f)
            else:
                originals.add(base)
    for f in duplicates:
        match = re.match(r'^(.*?)( - 복사본)?(\..+)?$', f)
        if match:
            base = (match.group(1) or '') + (match.group(3) or '')
            if base in originals:
                full_path = os.path.join(folder_path, f)
                os.remove(full_path)
                print(f'🗑️ 중복 파일 삭제됨: {f}')
    if not duplicates:
        print('✅ 삭제할 복사본이 없습니다.')

